python3 <<'PY'
import json, csv, statistics
from pathlib import Path

cohort = [json.loads(l)['sample_id'] for l in Path('/root/vdriftbench/data/v3.15_eval357.enriched.jsonl').read_text().splitlines() if l.strip()]

def load_jsonl(p):
    rows = {}
    for line in Path(p).read_text().splitlines():
        if line.strip():
            r = json.loads(line); rows[r['sample_id']] = r
    return rows

def csv_q(dir, sid):
    files = list(Path(dir).glob(f'*_jb_{sid}.csv'))
    if not files: return None
    with open(files[0], newline='', encoding='utf-8') as f:
        return int(float(next(csv.DictReader(f)).get('total_query_time') or 0))

methods = {
    'v3.15.1': lambda sid: len(load_jsonl('/root/vdriftbench/data/v3.15.1_run/results.jsonl')[sid]['rounds']),
    'PAIR': lambda sid: load_jsonl('/root/pair_baseline_v315_run/results.jsonl')[sid]['total_target_queries'],
    'CoP': lambda sid: csv_q('/root/cop/outputs/v315/deepseek-v4-pro_vdb_draft-model', sid),
    'PLAGUE': lambda sid: csv_q('/root/PLAGUE/outputs/v315/deepseek-v4-pro_vdb_draft-model', sid),
    'Crescendo': lambda sid: load_jsonl('/root/crescendo_baseline_v315_pro_genre/results.jsonl')[sid]['total_target_queries'],
}

for name, fn in methods.items():
    qs = [fn(s) for s in cohort]
    qs_sorted = sorted(qs)
    def pct(p):
        i = int(round((p/100)*(len(qs_sorted)-1)))
        return qs_sorted[i]
    ge20 = sum(1 for q in qs if q>=20)
    print(name, 'min', min(qs), 'p25', pct(25), 'p75', pct(75), 'max', max(qs), 'hit20', ge20)
